let mut tx = pool.begin().await?;                 // rollback on drop if not committed
for c in uow.added()   { insert_customer(&mut *tx, c).await?; }
for c in uow.dirty()   { update_customer(&mut *tx, c).await?; }
for id in uow.removed(){ delete_customer(&mut *tx, id).await?; }
tx.commit().await?;                               // atomic; uow.clear() afterwards
// diesel: conn.transaction(|conn| { ... }) commits on Ok, rolls back on Err

