conn.transaction::<_, diesel::result::Error, _>(|conn| {
    diesel::insert_into(users).values(name.eq("Ruby")).execute(conn)?;
    diesel::update(users.filter(id.eq(1))).set(active.eq(true)).execute(conn)?;
    Ok(())
})?;   // Ok commits; Err rolls back (Error::RollbackTransaction forces it)
